body.script:
function switchMode(mode){
    var sel = document.getElementById('mode_select');
    var man = document.getElementById('mode_manual');
    var btnSel = document.getElementById('btn_select');
    var btnMan = document.getElementById('btn_manual');
    if(mode === 'select'){
        sel.style.display = 'block'; man.style.display = 'none';
        btnSel.style.background='#1abc9c'; btnSel.style.color='#fff'; btnSel.style.borderColor='#1abc9c';
        btnMan.style.background='#fff'; btnMan.style.color='#555'; btnMan.style.borderColor='#ddd';
    } else {
        sel.style.display = 'none'; man.style.display = 'block';
        btnMan.style.background='#1abc9c'; btnMan.style.color='#fff'; btnMan.style.borderColor='#1abc9c';
        btnSel.style.background='#fff'; btnSel.style.color='#555'; btnSel.style.borderColor='#ddd';
    }
}

function toggleManual(sel, divId){
    var div = document.getElementById(divId);
    if(div) div.style.display = sel.value === 'manual' ? 'block' : 'none';
}

function s2SwitchMode(mode){
    var sel = document.getElementById('s2_mode_select');
    var man = document.getElementById('s2_mode_manual');
    var btnSel = document.getElementById('s2_btn_select');
    var btnMan = document.getElementById('s2_btn_manual');
    if(mode === 'select'){
        sel.style.display='block'; man.style.display='none';
        btnSel.style.background='#1abc9c'; btnSel.style.color='#fff'; btnSel.style.borderColor='#1abc9c';
        btnMan.style.background='#fff'; btnMan.style.color='#555'; btnMan.style.borderColor='#ddd';
    } else {
        sel.style.display='none'; man.style.display='block';
        btnMan.style.background='#1abc9c'; btnMan.style.color='#fff'; btnMan.style.borderColor='#1abc9c';
        btnSel.style.background='#fff'; btnSel.style.color='#555'; btnSel.style.borderColor='#ddd';
    }
}

function selectNum(btn, val, group){
    if(group === 'add'){
        document.querySelectorAll('#add_visa_grid .num-btn').forEach(function(b){b.classList.remove('active')});
        btn.classList.add('active');
        document.getElementById('additional_visas_input').value = val;
    } else if(group === 'final'){
        document.querySelectorAll('#final_visa_grid .num-btn').forEach(function(b){b.classList.remove('active')});
        btn.classList.add('active');
        document.getElementById('final_visa_input').value = val;
    } else {
        document.querySelectorAll('.num-btn').forEach(function(b){b.classList.remove('active')});
        btn.classList.add('active');
        document.getElementById('additional_visas_input').value = val;
    }
}
